for p in R.rglob('*'):
 if not p.is_file():continue
 rel=p.relative_to(R)
 if any(x in rel.parts for x in ['raw','prepared','__pycache__']):continue
 if rel.parts[0]=='sources' and rel.suffix=='.json':continue # do not redistribute entire third-party articles
 if rel.name.endswith('_predictions.npz') or rel.suffix=='.log' or rel.name in ['SHA256.json','R17_26_RESULTS.zip']:continue
 files.append(p)
sha={str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(files)};(R/'SHA256.json').write_text(json.dumps(sha,indent=2)+'\n')
with zipfile.ZipFile(R/'R17_26_RESULTS.zip','w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
 for p in files+[R/'SHA256.json']:z.write(p,p.relative_to(R))
with zipfile.ZipFile(R/'R17_26_RESULTS.zip') as z:assert z.testzip() is None
print('REPORTS_AND_ZIP',len(files),(R/'R17_26_RESULTS.zip').stat().st_size)
if __name__=='__main__':pass
